sales = [("north", 120), ("south", 95), ("north", 80), ("east", 60), ("south", 40)]
totals = {}
for region, amount in sales:
    totals[region] = totals.get(region, 0) + amount
best = None
for region in sorted(totals):
    print(f"{region}: {totals[region]}")
    if best is None or totals[region] > totals[best]:
        best = region
